    # Find anchor rows (positions with 5 in anchor column)
    first_anchor = None
    for r in range(rows):
        if grid[r][anchor_col] == anchor_val:
            first_anchor = r
            break

    if first_anchor is None:
        return [row[:] for row in grid]

    # Find pattern rows ordered by appearance
    pattern_rows_list = []
    for r in range(rows):
        has_pattern = any(grid[r][c] != 0 for c in range(cols))
        if has_pattern:
            pattern_rows_list.append(grid[r])

    if not pattern_rows_list:
        # No pattern rows found
        return [row[:] for row in grid]

    # Build output
    output = []
    for r in range(rows):
        if grid[r][anchor_col] == anchor_val:
            # This position is an anchor row - fill with pattern
            pattern_offset = (r - first_anchor) % len(pattern_rows_list)
            new_row = list(pattern_rows_list[pattern_offset])
        else:
            # Non-anchor row -> remain as is (or 0)
            new_row = [0] * cols
        output.append(new_row)

    return output

